function baslangicTahtasi() {
  return [null, null, null, null, null, null, null, null, null];
}

function hamleYap(tahta, index, isaret) {
  if (index < 0 || index > 8) return false;
  if (tahta[index] !== null) return false;
  const yeniTahta = tahta.slice();
  yeniTahta[index] = isaret;
  return yeniTahta;
}

function sonrakiOyuncu(isaret) {
  return isaret === 'X' ? 'O' : 'X';
}

function kazanan(tahta) {
  const kombinasyonlar = [
    [0, 1, 2],
    [3, 4, 5],
    [6, 7, 8],
    [0, 3, 6],
    [1, 4, 7],
    [2, 5, 8],
    [0, 4, 8],
    [2, 4, 6]
  ];
  for (const [a, b, c] of kombinasyonlar) {
    if (tahta[a] !== null && tahta[a] === tahta[b] && tahta[b] === tahta[c]) {
      return tahta[a];
    }
  }
  return null;
}

function beraberlikMi(tahta) {
  if (kazanan(tahta) !== null) return false;
  return tahta.every((hucre) => hucre !== null);
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { baslangicTahtasi, hamleYap, sonrakiOyuncu, kazanan, beraberlikMi };
}

